"""Build the public-facing AFTERFORM second-pass case study and living toolkit."""
from pathlib import Path
import html,json
R=Path(__file__).resolve().parent;ROOT=R.parent.parent;SITE=(ROOT/'dist/afterform') if (ROOT/'dist').exists() else ROOT/'afterform'
H=html.escape
art=json.loads((R/'refinement-artwork.json').read_text());brief=json.loads((R/'refinement-map.json').read_text())
def img(src,alt,cls=''):
 return f'<img src="{src}" alt="{H(alt)}" class="{cls}" loading="lazy">'
def figure(src,alt,cap='',cls=''):
 return f'<figure class="{cls}">{img(src,alt)}<figcaption>{cap or H(alt)}</figcaption></figure>'
def table(headers,rows,label='Specification'):
 return '<div class="full-table" tabindex="0" role="region" aria-label="'+H(label)+'"><table><thead><tr>'+''.join('<th scope="col">'+H(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(id,k,title,body,cls=''):
 return f'<section class="exhibit-section wrap {cls}" id="{id}"><header><span class="eyebrow">{k}</span><h2>{title}</h2></header>{body}</section>'
def nav(active):
 return '<header class="presentation-nav wrap"><a class="brand" href="index.html">afterform<span>AN ORIGINAL STUDIO CONCEPT</span></a><nav aria-label="Project">'+''.join(f'<a href="{u}" '+('aria-current="page"' if active==t else '')+'>'+t+'</a>' for t,u in [('Case study','../afterform.html'),('Studio standards','system.html'),('Artwork archive','identity.html'),('Try the product ↗','index.html')])+'</nav></header>'
def shell(title,body,active='',script=None,desc='AFTERFORM, a garment repair identity and product concept by Jocelyn Martinez.'):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#38233f"><title>'+H(title)+' — Afterform / Jocelyn Martinez</title><meta name="description" content="'+H(desc)+'"><link rel="icon" href="assets/system/micro-mark.svg"><link rel="stylesheet" href="afterform.css"><link rel="stylesheet" href="presentation.css"><link rel="stylesheet" href="refinement.css">'+(f'<script src="{script}" defer></script>' if script else '')+'</head><body><a class="skip" href="#main">Skip to content</a>'+nav(active)+'<main id="main">'+body+'</main><footer class="presentation-footer wrap"><a href="../index.html#work">← All of Jocelyn’s work</a><p>AFTERFORM · Self-directed, AI-assisted portfolio concept.<br>No operating studio, customer research or measured repair outcomes are claimed.</p><a href="refinement.html">Decisions & refinement record ↗</a></footer></body></html>'
def write(n,s):(SITE/n).write_text(s)
def links(items):return '<div class="evidence-links">'+''.join(f'<a href="{u}">{t}<span>{sub}</span></a>' for t,u,sub in items)+'</div>'
def gallery(stem,items):
 return '<div class="proof-gallery">'+''.join(figure(f'assets/system/{stem}-{n:02}.webp',title,f'{title}<span>{sub}</span>') for n,title,sub in items)+'</div>'

b='''<section class="system-hero"><div class="wrap"><span class="eyebrow">SECOND IMPRESSION / STUDIO STANDARDS / EDITION 02</span><h1>Keep the character.<br><em>Clarify the change.</em></h1><p class="lead">The AFTERFORM identity, from its smallest label to its largest invitation. A working system for the clothes people keep.</p><div class="hero-actions"><a class="button" href="downloads/AFTERFORM-Identity-Standards.pdf">Download the 16-page standards ↗</a><a href="#labels">Try the label system ↓</a></div></div></section><nav class="system-jump wrap" aria-label="Studio standards sections"><a href="#identity">Identity</a><a href="#type">Type & colour</a><a href="#labels">Labels</a><a href="#editorial">Editorial</a><a href="#environment">In the studio</a><a href="#campaign">Campaign</a><a href="#motion">Motion</a><a href="#downloads">Downloads</a></nav>'''
b+=section('identity','01 / IDENTITY','A wordmark.<br>A useful family.',f'''<p class="section-lead">The established typographic mark remains the anchor. New lockups explain the service; a compact signature and a simple joining symbol handle smaller contexts.</p>{img('assets/system/brand-system-board.svg','AFTERFORM system board: primary wordmark, compact signature, garment ID, next-action label and colour roles','system-board')}<p class="system-caption">A name, a visible change and a useful record. These three ideas organise the identity even when the logo is absent.</p><div class="system-marks">{figure('assets/system/lockup-horizontal.svg','Horizontal service lockup','Service lockup / website, correspondence')}{figure('assets/system/lockup-stacked.svg','Stacked service lockup','Stacked lockup / narrow panels')}{figure('assets/system/avatar.svg','Compact af signature','Compact signature / social avatar')}</div><div class="two-col"><div><h3>Typographic, with restraint.</h3><p>The master uses licensed Bodoni Moda outlines with a modest, consistent tracking adjustment. The letterforms are not presented as a custom typeface. The selected setting preserves the fluid reading of “afterform”; the earlier split construction remains in the exploration archive.</p></div><div><h3>Fewer strokes at small sizes.</h3><p>Fine display letterforms lose clarity at favicon scale. The micro mark retains only the functional joining idea. It is used where the full brand name is already available in the page title or surrounding interface.</p></div></div><div class="logo-sizing"><label for="logo-context">See the responsive identity<select id="logo-context"><option value="masthead">Web wordmark / 144 px</option><option value="lockup">Service lockup / 220 px</option><option value="avatar">Compact avatar / 48 px</option><option value="micro">Joining symbol / 24 px</option></select></label><div><img id="responsive-logo" src="assets/wordmark-plum.svg" alt="Afterform responsive logo specimen"><p id="logo-explanation" role="status">Primary wordmark at its digital minimum target.</p></div></div>{img('assets/system/clear-space.svg','Wordmark clear-space construction: half the lowercase height outside the visible outline','clear-space-board')}{table(['Rule','Application'],[['Clear space','At least 0.5 × lowercase height outside the visible outline; exported SVG padding is not the measurement.'],['Minimum target','Primary: 144 px / 35 mm. Service lockup: 220 px / 50 mm. Compact: 32 px. Micro symbol: 16–32 px. Actual-size proofs remain necessary.'],['Background','Plum on poplin or lilac. Lilac on plum. Solid black for one-colour applications.'],['Do not','Distort proportions, add shadows, outline the lettering, use a photo fill or run fine red lettering over lilac.']])}''')
b+=section('type','02 / FOUNDATIONS','One voice.<br>Different reading distances.','''<div class="color-roles"><article class="color-role dominant"><span class="eyebrow">DOMINANT / PLUM + LILAC</span><h3>Keep the<br>good part.</h3><p>Brand invitation, publication covers and quiet environmental presence.</p></article><article class="color-role quiet"><span class="eyebrow">QUIET / POPLIN + PLUM</span><h3>What needs<br>attention?</h3><p>Forms, records and information-heavy pages. Primary contrast: 13.32:1.</p></article><article class="color-role expressive"><span class="eyebrow">CAMPAIGN / VERMILION + POPLIN</span><h3>A change<br>worth seeing.</h3><p>One expressive moment. Essential text contrast: 5.15:1.</p></article></div><dl class="type-ladder"><div><dt>01 / DISPLAY<br>Bodoni Moda · 48–104 px</dt><dd class="display-spec">Good clothes.<br>Another chapter.</dd></div><div><dt>02 / EDITORIAL<br>Bodoni Moda · 28–36 px</dt><dd class="editorial-spec">The cloth has a say.<br>Start with what you notice.</dd></div><div><dt>03 / TASK<br>Karla · 17/27 px</dt><dd class="ui-spec">Describe the place that needs attention.<br>A preference is not a diagnosis.</dd></div><div><dt>04 / RECORD<br>Inconsolata · 13/18 px</dt><dd class="micro-spec">AF-S01 / M01 / REVISION 01<br>OBJECT → ATTENTION → NEXT ACTION</dd></div><div><dt>05 / DISTANCE<br>Karla Medium · installation-specific</dt><dd class="environment-spec">Proposal review →</dd></div></dl><div class="two-col"><p>Display text establishes the emotional premise. Karla carries labels, directions and decisions. Codes always sit beside plain language. Body copy is constrained to a comfortable measure, typically 45–70 characters.</p><p>Print body targets 11/16 pt; essential tag information targets at least 9/12 pt. The system does not force digital instructions into 8 px microcopy. Sign dimensions, mounting and letter height require a real-distance proof.</p></div>'''+table(['Token','Value','Behaviour'],[['Deep plum','#38233F','Primary text, identity and dark surfaces.'],['Vermilion','#BD3B2F','One emphasis or a changed-scope cue, with an explicit label.'],['Lilac','#D6C6EC','Supporting field, selected state and editorial relief.'],['Poplin','#FAF7F8','Primary reading background; white #FFFFFF for forms.'],['Secondary text','#6B586F','6.07:1 on poplin.'],['Success','#2B614C','6.76:1 on poplin, always paired with text.'],['Category','Words + M/F/A/Q codes','No additional category colours. A repair code is not a status.']],'Colour roles'))
b+=section('grammar','03 / GRAPHIC LANGUAGE','A practical grammar.','''<div class="grammar-rows"><article><span>01 / NAME THE PIECE</span><h3>Recognition first.</h3><p>A stable garment ID and a familiar name establish which piece is under discussion.</p></article><article><span>02 / SHOW THE CHANGE</span><h3>One intervention.</h3><p>A joining line, a material crop or a marked revision makes the relevant change visible. Decorative coordinates and fake barcodes have no role.</p></article><article><span>03 / KEEP THE RECORD</span><h3>A useful next step.</h3><p>A short information rail carries the repair type, version or action. It works in a label, a form and a publication margin.</p></article></div><p class="section-lead">A quiet label can omit imagery. A campaign can omit the code. The grammar is a hierarchy of meaning, not a requirement to fill every corner.</p>''')
b+=section('labels','04 / LABEL SYSTEM','Small format.<br>Serious information.','''<p class="section-lead">Try the operational states, monochrome treatment and a longer description. The system expands the format before it compromises essential type.</p><div class="label-workbench"><div class="workbench-controls"><label>Garment<select id="label-piece"><option value="shirt">The everyday shirt</option><option value="jeans">The familiar jeans</option><option value="jacket">The borrowed jacket</option></select></label><label>Workflow state<select id="label-state"><option value="review">Needs review</option><option value="changed">Scope changed</option><option value="agreed">Agreement recorded</option><option value="ready">Ready to collect</option></select></label><fieldset><legend>Content & production</legend><label><input type="checkbox" id="label-long">Use long-content specimen</label><label><input type="checkbox" id="label-mono">One-colour output</label></fieldset><button class="button" id="print-label">Print this specimen</button><p class="small muted">These are illustrative workflow states. They do not certify quality or record a real agreement.</p></div><div class="label-stage"><p id="label-size">Work label · 90 × 65 mm</p><article id="label-proof" class="label-proof" aria-label="Live label specimen"></article><p id="label-explanation"></p></div></div><p class="sr-only" role="status" id="label-announcer"></p><noscript><p>The interactive specimen needs JavaScript. The complete label system is also available in the PDF below.</p></noscript>'''+gallery('service',[(3,'The work ticket','100 × 150 mm / the record stays with the piece'),(4,'A larger object tag','72 × 115 mm / 4 mm hole, clear of copy'),(5,'The readable reverse','A real sample QR and the typed ID'),(6,'Needs review','90 × 65 mm / explicit next action'),(7,'Scope changed','The text, not colour alone, communicates the change'),(8,'Agreement recorded','The revision stays visible'),(9,'Ready to collect','Match garment and record at handover'),(10,'Record inside','50 × 50 mm / a functional envelope seal'),(11,'Spare-fastening envelope','60 × 80 mm finished / dimensional prototype')])+'''<p class="section-lead">The tag and seal attach to removable service packaging, not directly to delicate cloth. Materials, adhesive and hole strength need physical proofing. No fibre composition, care symbol, certification or barcode is invented.</p><a class="button primary" href="downloads/AFTERFORM-Service-Paper-System.pdf">Inspect all twelve service pieces ↗</a>''')
icons=['assess','join','approve','question','return','record','print','label','revise','piece']
b+=section('icons','05 / ICONOGRAPHY','Tools for understanding.','<div class="micro-family">'+''.join(figure('assets/icons/'+i+'.svg',i,i.capitalize()) for i in icons)+'</div><div class="two-col annotations"><p>24 px construction grid. 1.75 px strokes. Square ends and deliberate corners. The new print, label, revise and garment pictograms extend the established family. The garment pictogram is a general navigation cue, not a diagnosis diagram.</p><p>Text labels remain visible. Interface icons are decorative to screen readers when adjacent copy supplies the name. At environmental scale, the destination name remains primary; a small brand symbol never substitutes for a direction.</p></div>')
b+=section('editorial','06 / EDITORIAL','On keeping.<br>A complete second edition.','''<p class="section-lead">Twenty-four pages, four chapters. Invitation gives way to explanation, comparison and a useful takeaway. The twelve-page first edition remains in the archive.</p><div class="edition-spread">'''+img('assets/system/edition-04.webp','Opening spread, page 4: Keep the good part')+img('assets/system/edition-05.webp','Opening spread, page 5: material image and explanatory caption')+'''</div><div class="two-col"><div><h3>170 × 240 mm. Six folded sheets.</h3><p>The proposed saddle-stitched object uses 16 mm margins, a two-column underlying grid and a 6 mm spacing rhythm. Not every page exposes the grid. Large editorial openings give practical index and comparison pages room to breathe.</p></div><div><h3>Every page has actual content.</h3><p>Inside cover, contents, opening, image-led spread, finish comparison, taxonomy, request, proposal, decision, record, care boundaries, checklist, colophon and back cover. A readable HTML edition accompanies the visual pages.</p></div></div>'''+links([('Read all 24 pages','edition.html','Visual reader + complete text edition'),('Download the second edition','downloads/AFTERFORM-On-Keeping-Second-Edition.pdf','24 pages / vector typography / RGB design proof')]))
b+=section('paper','07 / EVERYDAY COMMUNICATION','The ordinary pieces<br>deserve good design.',gallery('service',[(1,'A clear intake brief','Garment, place and intention before a diagnosis'),(2,'A comparison on paper','Requested intention beside proposed changes'),(12,'A follow-up card','The next question starts with the record')])+'''<div class="two-col annotations"><p>The intake form, comparison sheet and work ticket use the same hierarchy as the interface. They make a service conversation easier to have, with enough space to read the information without scanning an ornamental layout.</p><p>The printable product brief is generated from the saved request. It has no fabricated signature, barcode or public link. A browser-local request cannot truthfully behave like a shared online record.</p></div><a class="button primary" href="index.html?study=brief">Try the printable request ↗</a>''')
b+=section('environment','08 / INFORMATION IN SPACE','Welcome.<br>Then help someone move.','''<div class="environment-art">'''+figure('assets/system/environment-01.webp','Studio window invitation','Window invitation / 600 × 900 mm')+'<div class="stacked">'+figure('assets/system/environment-02.webp','Three-destination studio directory','Directory / 500 × 400 mm')+figure('assets/system/environment-03.webp','Proposal review desk sign','Counter / 210 × 148 mm')+figure('assets/system/environment-04.webp','Collection point sign','Collection point / 400 × 200 mm')+'''</div></div><div class="two-col annotations"><p>The window is an invitation. The directory names destinations. The counter sign makes asking a question feel normal. The collection sign ends with the same action as the digital record: match the ID and keep the useful details.</p><p>These are dimensioned environmental studies, not installed signs. Arrows, mounting, glare and accessibility requirements need a real location. No fictional address, opening hours, floor plan or code-compliance claim is added.</p></div><a class="text-button" href="downloads/AFTERFORM-Environmental-Communication.pdf">Download the environmental set ↗</a>''')
social=[('social-announcement','Announcement','1080 × 1350 / one invitation, short support'),('social-editorial','Editorial image','1080 × 1350 / material-led discovery'),('social-information','Information carousel','1080 × 1350 / a useful three-part sequence'),('story-guide','Story','1080 × 1920 / interface-safe top and bottom'),('reel-cover','Reel cover','1080 × 1920 / centre the meaningful feed crop'),('return-reminder','Record reminder','1080 × 1350 / a reason to return')]
b+=section('campaign','09 / CAMPAIGN & COMMUNICATION','One idea.<br>A different job in each format.','''<p class="section-lead">The existing five-poster campaign stays. Six new digital masters extend the system by purpose: invite, explain, guide, identify and bring someone back.</p><div class="social-system">'''+''.join(figure('assets/system/'+n+'.svg',title,f'<a href="assets/system/{n}.svg" download>{title} / SVG ↓</a> · <a href="assets/system/{n}.png" download>PNG ↓</a><span>{H(sub)}</span>') for n,title,sub in social)+'''</div><div class="two-col annotations"><p>Story layouts protect top and bottom interface areas. The reel-cover title sits inside the central square crop. Information cards use a sequence rather than a resized poster. All type is authored as vector outlines.</p><p>The existing service email remains deliberately quiet: the next useful action is reviewing a proposal. No launch date, event, offer or business claim has been fabricated to fill a template.</p></div><a class="text-button" href="identity.html#campaign">See the five retained posters ↗</a>''')
b+=section('motion','10 / MOTION','Join.<br>Then settle.','''<div class="motion-layout"><div class="motion-stage is-settled" id="motion-stage"><strong>Keep the character.</strong><div class="brand-join" aria-hidden="true"><span></span></div><strong>Clarify the change.</strong><span>AFTERFORM / SECOND IMPRESSION</span></div><div><div class="motion-controls"><button class="button primary" id="play-brand-motion">Play once</button><button class="button" id="stop-brand-motion" disabled>Stop</button></div><p id="motion-state" role="status">A still composition until you choose to play.</p><p>A single 1.2-second identity demonstration connects two ideas, then stops. Everyday UI feedback is shorter: 160 ms for border or colour; 280 ms for a joining-rule reveal.</p><p>Reduced motion displays the completed frame immediately. Form errors and status messages never wait for an animation.</p></div></div>''')
downloads=[('Identity standards','AFTERFORM-Identity-Standards.pdf','16 pages'),('On keeping / second edition','AFTERFORM-On-Keeping-Second-Edition.pdf','24 pages'),('Service paper system','AFTERFORM-Service-Paper-System.pdf','12 pieces / mixed formats'),('Environmental communication','AFTERFORM-Environmental-Communication.pdf','4 dimensioned studies')]
b+=section('downloads','11 / TOOLKIT','A system someone else<br>can actually use.',links([(t,'downloads/'+f,sub+' / PDF') for t,f,sub in downloads])+'''<div class="inline-downloads"><a href="assets/system/lockup-horizontal.svg" download>Service lockup SVG ↓</a><a href="assets/system/lockup-stacked.svg" download>Stacked SVG ↓</a><a href="assets/system/avatar.svg" download>Avatar SVG ↓</a><a href="assets/system/micro-mark.svg" download>Micro mark SVG ↓</a><a href="assets/system/tokens.json" download>Design tokens JSON ↓</a></div><p class="section-lead">The source contains font licences, editable HTML/CSS/JavaScript, dimensioned PDF authoring code, local images and all SVG masters. The downloadable artwork is a design handoff, not a production certification.</p><p class="small muted">Physical samples, printer profiles, QR destinations and accessibility in a real setting still need validation. The portfolio remains honest about what is designed and what has been tested.</p>''')
write('system.html',shell('Studio standards',b,'Studio standards','system.js'))

# Publication reader: all pages remain available without JavaScript; enhanced spread navigation.
pages=art['AFTERFORM-On-Keeping-Second-Edition.pdf'];spreads=[[1]]+[list(range(i,i+2)) for i in range(2,24,2)]+[[24]]
b='''<section class="reader-heading wrap"><span class="eyebrow">ON KEEPING / SECOND EDITION</span><h1>A guide to the next chapter.</h1><p>Twenty-four pages. Open the spreads, inspect the typography, or read the text edition below.</p><a class="text-button" href="downloads/AFTERFORM-On-Keeping-Second-Edition.pdf">Download the 24-page PDF ↗</a></section><div class="reader-controls wrap"><button class="button" id="previous-spread">← Previous</button><label for="spread-select">Spread <select id="spread-select">'''+''.join(f'<option value="{i}">{"–".join(map(str,p))}</option>' for i,p in enumerate(spreads))+'''</select></label><button class="button" id="next-spread">Next →</button><span id="reader-status" role="status"></span><a class="text-button" href="#text-edition">Read the text ↓</a></div><section class="book-spreads wrap" aria-label="Publication spreads">'''
for i,nums in enumerate(spreads):
 b+=f'<div class="book-spread {"single" if len(nums)==1 else ""}" data-spread="{i}" data-pages="{",".join(map(str,nums))}">'+''.join(img(f'assets/system/edition-{n:02}.webp',f'Page {n}: '+pages[n-1]['title']) for n in nums)+'</div>'
b+='</section>'+section('text-edition','READABLE EDITION','Every page, in text.','<div class="readable-edition">'+''.join(f'<details><summary>{i:02} / {H(p["title"])}</summary>'+''.join('<p>'+H(t)+'</p>' for t in p['text'] if t not in ['ON KEEPING / SECOND EDITION',str(i).zfill(2)])+'</details>' for i,p in enumerate(pages,1))+'</div>')
write('edition.html',shell('On keeping / second edition',b,script='edition.js'))

# 15-phase refinement record. Explicit evidence, decisions, trade-offs and deliverable matrix.
phase_titles=['Project audit','Visual identity expansion','Graphic language','Deliverable ecosystem','Editorial & print','Campaign & communication','Information & environmental design','UX expansion','UI expansion','Design system','Motion','Accessibility','Case-study art direction','Hero assets','Employer audit']
ph=[]
ph.append('<div class="audit-four">'+''.join('<article><h3>'+k.upper()+'</h3><ul>'+''.join('<li>'+H(x)+'</li>' for x in brief['audit'][k])+'</ul></article>' for k in ['keep','refine','expand','replace'])+'</div><p>The second pass preserves the concept and its strongest work. The opportunity is depth: clearer identity rules, more complete editorial content, real operational graphics and two useful additions to the product.</p>')
ph.append('''<p><strong>Positioning:</strong> a garment-repair studio that treats emotional value and practical clarity as equally important. The personality stays candid, material-aware, expressive and considerate.</p><p><strong>Logo architecture:</strong> retain the outlined primary wordmark. Add a horizontal service lockup, stacked lockup, compact social avatar and small joining symbol. The micro mark is a functional reduction, not an invented certification seal.</p><p><strong>Typography:</strong> Bodoni Moda establishes character; Karla carries tasks and directions; Inconsolata supports IDs and revisions. The primary mark is a type-based design using licensed outlines. The selected tracking is restrained, and the 16 px symbol removes delicate display strokes.</p>'''+table(['Decision','Alternative considered','Tradeoff and validation'],[['Keep the current palette','Introduce another fashion palette','Continuity makes the project recognisable. Distinction comes from better behaviour and composition, not extra colours.'],['Simplify the micro mark','Shrink the full wordmark','Less naming information; requires the full name in the surrounding interface. Test recognition at 16, 24 and 32 px.'],['Explicit colour pairs','Use every colour on every background','Limits some expressive combinations to preserve readable information. Print colour still needs a stock-specific proof.']]))
ph.append('''<p><strong>Design grammar:</strong> name the piece; show one relevant change; keep the record. A stable garment ID, a repair description and a next-action zone organise the system. A joining line can be continuous, visibly interrupted or awaiting advice; it never replaces its text label.</p><p>Ten functional icons now share a 24 px grid and 1.75 px square-ended strokes. Six existing action icons are retained; print, label, revise and garment extend the family. No decorative arrows, fake barcodes, invented wash symbols or certification marks are introduced.</p><p>The label workbench shows four workflow states, three garment records, monochrome output and a long-content specimen. Long content moves to a taller tag instead of forcing smaller type. A 4 mm tag hole is separated from the wordmark and all essential information.</p><p><a href="system.html#labels">Inspect and manipulate the label system ↗</a></p>''')
matrix_rows=[[H(g),H(d),'<span class="matrix-status">'+H(pr)+'</span>',H(why)+'<br><strong>'+H(status)+'</strong>'] for g,d,pr,why,status in brief['deliverables']]
ph.append('<p class="matrix-intro">The map was defined before the expansion. Essential and the strongest high-value work were executed. Optional and unnecessary outputs remain explicitly separate so the project does not grow through invented business activity.</p>'+table(['Category','Touchpoint','Priority','Reason / decision'],matrix_rows,'Master deliverable selection map'))
ph.append('''<p><strong>On keeping:</strong> expanded from twelve to twenty-four pages while retaining the original edition. The new object includes an inside cover, contents, opening spread, image-led study, two finish directions, taxonomy, intake explanation, request/proposal comparison, decision paths, physical/digital record, care boundaries, checklist, colophon and back cover.</p><p><strong>Production concept:</strong> 170 × 240 mm, saddle stitch, six folded sheets, 16 mm outer margins and a 6 mm spacing rhythm. Proposed stock: 120 gsm uncoated text and 200 gsm cover. These are proposed specifications; grain, creep, gutter, colour and binding need a paper proof and printer review. The PDF is in reading order.</p><p><strong>Operational print:</strong> twelve pieces include an A5 intake brief, A5 comparison, 100 × 150 mm work ticket, 72 × 115 mm tag front and reverse, four 90 × 65 mm workflow labels, a 50 mm seal, a 60 × 80 mm spare-fastening envelope net and an A6 follow-up card. The previous return band and sleeve remain available.</p><p><strong>Material logic:</strong> keep labels on removable packaging; do not put untested adhesive on garments. The envelope carries a spare fastening and record ID. It has a 20 mm closing flap, 10 mm glue tab and 15 mm bottom flap; the drawn net is a prototype for fit testing.</p>'''+links([('Read the expanded publication','edition.html','All 24 pages and a readable text alternative'),('Inspect the service artwork','downloads/AFTERFORM-Service-Paper-System.pdf','Twelve practical pieces at proposed dimensions')]))
ph.append('''<p>The five existing A3 posters already demonstrate strong variation: typographic invitation, garment image, finish comparison, process and repair index. They are kept.</p><p>Six new SVG masters expand the digital campaign by communication task. The announcement uses one clear invitation. The editorial frame leads with material. The information frame explains three useful details. Story artwork reserves top and bottom interface zones. The reel title remains in the central square crop. The reminder makes the garment ID a reason to return.</p><p>The existing responsive service email remains a calm route back to the proposal. No fictional sale, opening date, special offer, event or customer quote has been invented to justify additional assets.</p><p><a href="system.html#campaign">View the complete campaign extension ↗</a></p>''')
ph.append('''<p>A four-level environmental hierarchy distinguishes invitation, navigation, conversation and handover. A 600 × 900 mm window graphic introduces the service; a 500 × 400 mm directory names three destinations; an A5 landscape counter sign normalises questions; a 400 × 200 mm collection sign connects the piece to its record.</p><p>Information design carries the experience: the repair index preserves plain-language labels, request and proposal appear side by side, and label zones separate object identity from repair type and changing status. A revision is never confused with a permanent garment ID.</p><p>The arrows are explicitly a direction study. A real site plan, mounting height, glare, lighting, accessibility review and distance test are necessary before installation. A geographical map and fabricated address would have no legitimate role.</p>''')
flow_rows=[['Discover a repair','Plain-language search or repair category','No results offers assessment or a reset. No diagnosis required.','A relevant service detail.'],['Describe a garment','Choose garment, place and finish preference','Required fields identify the correction. Back preserves the draft. Not sure remains valid.','A reviewed, saved local request.'],['Review a proposal','Original intention and illustrative assessed approach','Question stays pending; approval can be undone; saving revisions invalidates the previous decision.','An explicit example decision for the current revision.'],['Carry the request','Saved request → paper brief','Only saved data prints. No false public QR for browser-local information. Text download provides another copy.','A readable brief marked as a description, not authorisation.'],['Return with a piece','Printed sample ID or typed lookup → garment record','Unknown ID explains the sample scope. New intake inherits context but leaves the original record unchanged.','A fresh, linked assessment draft.']]
ph.append('''<p><strong>Users:</strong> a person who wants to keep a garment but lacks repair vocabulary, and a studio that needs a clear description without mistaking a preference for an achievable result. These are working assumptions, not interview findings.</p><p><strong>Journey:</strong> a window or campaign introduces repair; the desk helps describe the piece; the printable brief carries that intention; assessment adds practical limits; the comparison supports a decision; the tag and record support handover and a later request.</p>'''+table(['Flow','Entry and intent','Decision / alternate path','Completion'],flow_rows,'Primary product flows')+'''<p><strong>Architecture:</strong> Find a repair → service detail → three-step request → My request → proposal or paper brief. The garment-record area supports typed lookup, individual records, downloads and a linked new assessment. Screen-study URLs are isolated from saved visitor data.</p><p><strong>Boundary:</strong> no accounts, shipping, scheduling, payment or live studio messaging. Those would require operational evidence and a real service. The prototype continues to use local storage with an explicit in-memory fallback.</p>''')
ph.append('''<p>Nine interactive studies now cover discovery, garment details, finish, review, proposal, garment record, empty search, paper brief and returning intake. The new print view uses a precise three-zone hierarchy and carries the request ID, revision, garment, repair type, place, material and preference.</p><p>On mobile, product controls remain ahead of imagery; the step rail becomes compact; comparisons stack in reading order. The paper brief collapses metadata into a single column. The label workbench moves controls above the specimen. Editorial spreads become readable single pages rather than tiny facing pages.</p><p>Focus-visible controls, persistent labels, native radio groups, validation messages, status announcements, confirmation dialogs and missing-route recovery remain. The record lookup now clears stale error semantics when the ID is edited.</p><p><a href="screens.html">Inspect all nine interactive studies ↗</a></p>''')
ph.append('''<p>The toolkit includes a sixteen-page standards manual, outlined SVG masters, four new pictograms, six new campaign masters, one brand-system board, colour and spacing tokens, print authoring source and the working HTML/CSS/JavaScript.</p>'''+table(['Foundation','Rule','Application'],[['Spacing','4 px base; 8/12/16/24/32/48/64/96 steps','Controls, metadata, page rhythm. Editorial uses a separate 6 mm rhythm.'],['Borders / shape','1 px rules, square corners; selected controls use a stronger border','The paper-record character remains visible in the interface.'],['Elevation','Restrained document shadow only when it communicates a separate sheet','No floating glass cards or implied 3D devices.'],['Components','Repair row, code, finish choice, field, step rail, comparison, decision panel, notice, record and paper brief','Components follow the actual repair task, not a generic UI inventory.'],['States','Default, hover, focus, pressed, disabled, loading specimen, empty, validation, storage failure, approval and undo','Status text accompanies colour and motion.'],['Print / digital link','Stable sample IDs; separate local request IDs; visible revision numbers','QR opens a fixed sample record. Private local data is never encoded as a public record.']]))
ph.append('''<p>The motion specimen plays only when requested. A joining line progresses between the two brand statements over 1.2 seconds, then becomes still. Stop shows the final composition immediately. Reduced-motion preferences skip the movement entirely.</p><p>UI feedback uses 160 ms colour/border transitions and a 280 ms joining reveal where appropriate. Navigation does not depend on animated entrances, and feedback does not wait for a decorative sequence.</p><p>Loading is presented as an explicit demonstration, not a fabricated backend request. The prototype does not add an artificial delay to work that completes locally.</p><p><a href="system.html#motion">Play the motion specimen ↗</a></p>''')
ph.append('''<p><strong>Digital:</strong> the retained palette provides 13.32:1 for plum/poplin, 8.88:1 for plum/lilac and 5.15:1 for vermilion/poplin. Vermilion/lilac is 3.43:1 and is restricted to large display text; it does not carry small instructions. Focus, text labels and selected borders provide non-colour cues.</p><p><strong>Reading:</strong> UI body remains 17 px; regular labels target at least 14 px. The record uses small secondary metadata only when it is not the primary instruction. The publication has a complete HTML text alternative. New icon buttons are not introduced without names.</p><p><strong>Physical:</strong> the new larger tags protect essential 9 pt type. Uncoated, low-glare materials are proposed. Actual-size reading, hole clearance, folds, adhesive, QR scanning and environmental viewing distances still need a physical proof.</p><p><strong>Verification boundary:</strong> source-level and DOM checks can verify flows, state changes, links and contrast calculations. They do not establish browser layout quality, assistive-technology usability or WCAG conformance. Manual browser, keyboard, screen-reader and print tests remain necessary.</p>''')
ph.append('''<p>The case study now starts with the identity and the actual service premise, then exposes the complete touchpoint journey. It alternates a dense system board, a quiet explanation, a full editorial spread, small paper objects, a product sequence and a contextual physical view.</p><p>Flat work is primary evidence: recruiters can inspect outlined marks, label hierarchy, publication pages, environmental typography and working interface states. Contextual images support material and scale; they do not conceal the artwork or stand in for production files.</p><p>Captions identify what an image proves. Generated material and application images remain labelled as illustrative. The portfolio contains no fictional customers, interviews, metrics, launches or installed signage.</p>''')
ph.append('''<p><strong>Editorial moment:</strong> pages 4–5 pair a vermilion typographic statement with a large garment crop and one specific caption. Pages 6–7 move from material detail to the limits of assessment. They are shown as actual facing artwork, with no device frame.</p><p><strong>Brand moment:</strong> the system board combines the established wordmark, compact signature, garment ID, next-action label and colour roles. The composition is authored as SVG, so its text and spacing remain exact.</p><p><strong>Product moment:</strong> the nine-state explorer connects request, proposal and brief. The central comparison is live, with question, approval, undo and revision behaviour.</p><p><strong>Physical moment:</strong> the existing return-kit application sits beside the actual band, sleeve, new spare-fastening net and record seal. The image is a contextual illustration; the flat designs remain authoritative.</p><p><strong>Ecosystem moment:</strong> a final composition pairs the identity board with publication, intake brief, tag and window artwork. Each image also links to its full page or source PDF so a viewer can inspect the detail.</p>''')
employers=[['Graphic designer','24-page editorial sequence, twelve practical paper pieces, five retained posters and six new campaign masters','Explain hierarchy, grid, scale and how long content changes the format.'],['Visual designer','Material crops, distinctive palette, varied pacing, brand board and channel-specific compositions','Explain why a quiet comparison sits next to an expressive invitation.'],['Brand designer','Responsive identity, minimum-size rules, clear space, colour behaviour, grammar and standards manual','Explain the difference between a full name, service lockup, avatar and micro symbol.'],['UX designer','Plain-language taxonomy, uncertainty handling, version-sensitive decisions and return flow','Explain why the new brief cannot pretend to be a public online record.'],['UI / interaction designer','Nine interactive studies, form states, label workbench and opt-in motion','Explain mobile prioritisation, focus, status and reduced-motion behaviour.'],['Product designer','Connected request, assessment, decision, record and another visit','Explain scope restraint: no fabricated logistics, payment or operational promises.']]
ph.append(table(['Hiring lens','Concrete evidence','Interview discussion'],employers,'Employer recognition audit')+'''<h3>What still needs real evidence</h3><p>Observe how people describe a damaged garment. Ask repairers what information they need before assessment. Test whether people distinguish a preference, a proposal and approval. Print and scan the tags at actual size. Fold the packaging nets. Test the responsive prototype with keyboard and assistive technology.</p><p>These gaps cannot be solved honestly by inventing participants or success metrics. The new work supplies specific material for validation; it does not claim validation happened.</p><h3>Five memorable decisions</h3><ol><li>A joining rule expresses the repair and becomes a functional finish distinction.</li><li>A stable ID connects paper, product and a later conversation.</li><li>A label grows before its essential text shrinks.</li><li>A changed proposal requires a new decision.</li><li>The brand can be expressive while the task remains quiet.</li></ol>''')
b='''<section class="system-hero"><div class="wrap"><span class="eyebrow">AFTERFORM / SECOND-PASS DESIGN RECORD</span><h1>More depth.<br><em>The same clear idea.</em></h1><p class="lead">The complete audit, deliverable map, implemented changes and employer evidence for AFTERFORM’s flagship refinement.</p><div class="hero-actions"><a class="button" href="../afterform.html">View the finished case study ↗</a><a href="system.html">Open the working toolkit ↗</a></div></div></section><nav class="blueprint-toc wrap" aria-label="Refinement phases">'''+''.join(f'<a href="#phase-{i}">{i:02} / {t}</a>' for i,t in enumerate(phase_titles,1))+'</nav>'
for i,(t,body) in enumerate(zip(phase_titles,ph),1):b+=section('phase-'+str(i),f'PHASE {i:02}',t,body,'new-phase')
write('refinement.html',shell('Flagship refinement / all fifteen phases',b))

# Reframe the case study around the ecosystem, keeping the established material images and product.
def ci(name,alt,cls=''):return img('afterform/assets/'+name,alt,cls)
def sec(id,k,title,body):return section(id,k,title,body)
b='''<section class="wrap case-signature"><div><span class="eyebrow">IDENTITY × GRAPHIC DESIGN × PRODUCT / SELF-DIRECTED</span><h1>afterform</h1><p>A considered next chapter<br>for the clothes you keep.</p><div class="hero-links"><a class="button primary" href="afterform/index.html">Try the repair desk ↗</a><a class="text-button" href="afterform/system.html">Explore the studio standards</a></div></div><figure>'''+ci('system/brand-system-board.svg','AFTERFORM identity board showing typography, compact mark, record label and palette')+'''<figcaption>SECOND IMPRESSION / ONE IDENTITY, MANY USEFUL FORMS</figcaption></figure></section><section class="case-summary wrap"><h2>The repair is a change.<br>The person deserves<br>to understand it.</h2><div><p>AFTERFORM is a garment-repair studio concept connecting a clear request, a considered proposal and a record that stays with the piece. Its identity works just as hard on a small label as it does in the interface.</p><dl><div><dt>My scope</dt><dd>Concept, UX/UI, identity, editorial, campaign, service graphics, print systems and front-end prototype, with AI assistance.</dd></div><div><dt>Context</dt><dd>Self-directed concept. No commissioned client or operating studio.</dd></div><div><dt>Evidence</dt><dd>Secondary research, heuristic reasoning and implementation checks. Primary user and physical testing remain.</dd></div></dl></div></section><nav class="case-index wrap" aria-label="Case study sections"><a href="#experience">Experience</a><a href="#identity">Identity</a><a href="#editorial">Editorial</a><a href="#product">Product</a><a href="#physical">Physical</a><a href="#reflection">Reflection</a></nav>'''
b+=sec('experience','01 / THE EXPERIENCE','From the first question<br>to the next repair.','''<div class="two-col"><div><h3>For the person keeping a piece.</h3><p>They know where something is worn, but may not know the material or method. The interface begins with their observation and keeps “Not sure” available.</p></div><div><h3>For the studio making a promise.</h3><p>A preference is not a practical repair plan. The proposed scope, finish and price need to be understood before a decision is recorded.</p></div></div><div class="touchpoint-path"><article><span class="eyebrow">01 / NOTICE & DESCRIBE</span><h3>Start with the piece.</h3><p>A campaign introduces the possibility. A plain-language index helps someone describe the garment, place and intention.</p><a href="afterform/index.html">Explore the repair desk ↗</a></article><article><span class="eyebrow">02 / CONSIDER & DECIDE</span><h3>Make the change explicit.</h3><p>The request and proposed approach stay together. Questions keep the decision pending; a revision resets approval.</p><a href="afterform/index.html?study=proposal">Review an example proposal ↗</a></article><article><span class="eyebrow">03 / KEEP & RETURN</span><h3>Carry the useful details.</h3><p>The tag opens a sample record. That record can begin a fresh request without overwriting its earlier story.</p><a href="afterform/index.html?study=return">Start from an earlier record ↗</a></article></div>''')
b+='''<section class="signature-band"><div class="wrap"><span class="eyebrow">THE DESIGN GRAMMAR</span><h2>Name the piece.<br>Show the change.<br>Keep the record.</h2><p>These three instructions shape the hierarchy of a page, the zones on a tag and the steps in the product. The identity carries meaning even when its logo is absent.</p></div></section>'''
b+=sec('identity','02 / VISUAL IDENTITY','Fashion character.<br>Workshop clarity.',ci('system/brand-system-board.svg','The complete AFTERFORM identity system','system-board')+'''<div class="two-col annotations"><div><h3>Keep the identity. Deepen its rules.</h3><p>Plum, vermilion, lilac and poplin remain. Bodoni Moda introduces the emotional value of clothing; Karla makes decisions and directions clear; Inconsolata keeps the records consistent.</p></div><div><h3>Responsive, not ornamental.</h3><p>The wordmark gains service lockups, a compact avatar and a simplified small-size symbol. The sixteen-page standards manual documents clear space, size, colour behaviour, imagery, labels and motion.</p></div></div><a class="button primary" href="afterform/system.html#identity">Inspect the complete identity ↗</a>''')
b+=sec('editorial','03 / EDITORIAL DESIGN','A publication with<br>something useful to say.','''<div class="edition-spread">'''+ci('system/edition-04.webp','Page 4: Keep the good part, large vermilion typographic composition')+ci('system/edition-05.webp','Page 5: cotton garment and considered repair')+'''</div><div class="two-col"><div><h3>On keeping / second edition.</h3><p>Twenty-four pages move from an invitation to a decision. The four-part sequence covers the piece, the choice, the agreement and the next chapter.</p><p>170 × 240 mm, proposed saddle stitch, a two-column underlying grid and a 6 mm spacing rhythm. The original twelve-page guide is preserved in the archive.</p></div><div><h3>The pacing carries the explanation.</h3><p>Full material crops make room for quiet reading pages. A repair index handles density. Facing request/proposal pages expose the difference between intention and assessment.</p><a class="text-button" href="afterform/edition.html">Read all 24 pages and the text edition ↗</a></div></div><div class="edition-spread">'''+ci('system/edition-14.webp','Page 14: the original requested intention')+ci('system/edition-15.webp','Page 15: what the assessment adds')+'''</div>''')
b+=sec('labels','04 / LABELS & INFORMATION','A small label.<br>A clear next action.','<div class="proof-gallery">'+''.join(figure('afterform/assets/system/service-'+str(n).zfill(2)+'.webp',t,t+'<span>'+sub+'</span>') for n,t,sub in [(4,'Object tag','ID + plain-language repair'),(6,'Review label','What happens next is written out'),(7,'Changed scope','A new version needs a fresh decision')])+'''</div><div class="two-col annotations"><p>The fixed reading order is object → attention → next action. A code helps the studio; a description helps the person. Status is never communicated by colour alone.</p><p>Content tests show a deliberate tradeoff: longer descriptions move to a taller tag, rather than shrinking the essential type. Monochrome output preserves every information cue.</p></div><a class="button primary" href="afterform/system.html#labels">Try the live label workbench ↗</a>''')
b+=sec('product','05 / THE DIGITAL PRODUCT','The second conversation<br>is the important screen.','''<p class="section-lead">The product makes a proposed change inspectable. A question is a valid next step; approval is a reversible state attached to the current revision.</p><div class="product-embed"><div><span>INTERACTIVE STUDY / EXAMPLE DATA / YOUR SAVED REQUEST IS UNCHANGED</span><a href="afterform/index.html?study=proposal">Open full size ↗</a></div><iframe src="afterform/index.html?study=proposal" title="Interactive proposal comparison with question, approval and undo" loading="lazy"></iframe></div><div class="grammar-rows"><article><span>REQUEST</span><h3>A preference.</h3><p>The person describes the piece, the location and the intended finish. They are not asked to diagnose the repair.</p></article><article><span>ASSESSMENT</span><h3>Practical context.</h3><p>The example studio proposal adds scope, finish limits and an illustrative price. Timing is explicitly unconfirmed.</p></article><article><span>DECISION</span><h3>A recorded choice.</h3><p>A question keeps the proposal pending. Saving changed details invalidates the earlier approval and asks for a new review.</p></article></div><a class="button primary" href="afterform/screens.html">Explore all nine interactive screen studies ↗</a>''')
b+=sec('connection','06 / PHYSICAL × DIGITAL','The request can leave<br>the screen.','''<div class="two-col"><div>'''+ci('system/service-01.webp','Flat A5 repair brief, showing clear name, code, description and assessment context')+'''</div><div><h3>A paper brief from real prototype data.</h3><p>The saved request produces a print view and downloadable text copy. The ID and revision identify which details are being discussed. A visible statement distinguishes description from permission to begin work.</p><p>A private local request gets no pretend public QR. Fixed sample garment records have real QR destinations and typed-ID fallbacks.</p><a class="button primary" href="afterform/index.html?study=brief">Try the paper brief ↗</a><h3 style="margin-top:35px">A return visit keeps its context.</h3><p>The original record can seed a new assessment with the garment already identified. The earlier record remains unchanged, and the new request still asks the person to check the place and material.</p><a class="text-button" href="afterform/index.html?study=return">Try the returning-garment flow ↗</a></div></div>''')
b+=sec('physical','07 / THE RETURN EXPERIENCE','The piece and its record,<br>kept together.','''<figure class="application-image">'''+ci('return-kit.webp','Illustrative AFTERFORM return kit with guide, band, record sleeve and tag')+'''<figcaption>Contextual generated illustration. The exact content, dimensions and construction are supplied as authored flat artwork.</figcaption></figure><div class="proof-gallery">'''+figure('afterform/assets/print/packaging-01.webp','Existing return-band flat artwork','Return band<span>Retained / dimensional panel artwork</span>')+figure('afterform/assets/system/service-11.webp','Spare-fastening envelope net','Spare-fastening envelope<span>New / 60 × 80 mm finished proposal</span>')+figure('afterform/assets/system/service-10.webp','Record-inside envelope seal','Record inside<span>A functional seal, not a certification</span>')+'''</div><p class="section-lead">The materials support a natural handover: a band keeps the information with the piece, a sleeve protects the record, and a small envelope keeps a spare fastening from becoming loose. No merchandise or luxury box is added without a role.</p><a class="text-button" href="afterform/system.html#paper">Inspect the complete service paper system ↗</a>''')
b+=sec('campaign','08 / CAMPAIGN','Variation with<br>a recognisable voice.','<div class="poster-wall">'+''.join(figure(f'afterform/assets/print/poster-{i:02}.webp',f'AFTERFORM campaign poster {i}',cap) for i,cap in enumerate(['01 / Type','02 / Material','03 / Finish','04 / Process','05 / Index'],1))+'''</div><p class="section-lead">The five original poster compositions stay. The new announcement, editorial, information, story, reel-cover and reminder formats adapt the hierarchy for different reading speeds and crops.</p><div class="social-system">'''+''.join(figure('afterform/assets/system/'+n+'.svg',t,t+'<span>'+sub+'</span>') for n,t,sub in [social[1],social[2],social[3]])+'''</div><a class="text-button" href="afterform/system.html#campaign">Explore all campaign masters ↗</a>''')
b+=sec('environment','09 / ENVIRONMENTAL INFORMATION','A welcome is expressive.<br>A direction is clear.','''<div class="environment-art">'''+figure('afterform/assets/system/environment-01.webp','Large studio window invitation','Window / brand invitation')+'<div class="stacked">'+figure('afterform/assets/system/environment-02.webp','Three destination studio directory','Directory / destination before decoration')+figure('afterform/assets/system/environment-03.webp','Proposal review desk sign','Counter / questions are part of the service')+'''</div></div><p class="section-lead">Display typography welcomes. Karla names destinations. The same service stages appear in the printed materials and the interface. These are dimensioned design studies; a real site and physical legibility checks are still required.</p><a class="text-button" href="afterform/system.html#environment">Inspect the environmental set ↗</a>''')
b+=sec('system','10 / SYSTEM & ACCESSIBILITY','The identity survives<br>the practical details.','''<div class="decision-strip"><article><span>RESPONSIVE IDENTITY</span><h3>Less information,<br>at the right scale.</h3><p>A service lockup belongs on a larger panel. A compact mark belongs in an avatar. At 16 px, the joining symbol removes fragile display detail.</p></article><article><span>ACCESSIBLE BEHAVIOUR</span><h3>Readable choices.<br>Visible feedback.</h3><p>Persistent form labels, focus rings, text-based status, required-choice errors, reduced motion and a complete HTML publication text edition.</p></article><article><span>IMPLEMENTATION</span><h3>One connected<br>set of states.</h3><p>Drafts, local requests, questions, approval, revisions, paper briefs and returning records follow explicit rules. Screen studies remain isolated from visitor data.</p></article></div><div class="two-col annotations"><p>Measured text pairs: plum/poplin 13.32:1, plum/lilac 8.88:1, vermilion/poplin 5.15:1. Vermilion on lilac is reserved for large display text.</p><p>Colour and DOM checks do not establish full accessibility. Manual browser, keyboard, screen-reader and actual-size print testing remain necessary.</p></div><a class="button primary" href="afterform/system.html#motion">Inspect the toolkit and motion ↗</a>''')
b+=sec('ecosystem','11 / ONE DESIGNED WORLD','One language.<br>Many useful forms.','''<div class="ecosystem-board">'''+ci('system/brand-system-board.svg','Identity system board')+'<div>'+ci('system/edition-01.webp','On keeping second edition cover')+ci('system/service-01.webp','Repair brief')+ci('system/service-04.webp','Garment tag')+ci('system/environment-01.webp','Window graphic')+'''</div></div><p class="section-lead">The graphic system helps people recognise the piece, understand a proposed change and carry useful information into the next conversation. The physical and digital work solve the same problem.</p>''')
b+=sec('reflection','12 / REFLECTION','What this work proves.<br>What still needs evidence.','''<div class="two-col"><div><h3>Designed and implemented.</h3><p>A distinctive identity with a transferable standards manual. A complete editorial sequence. Practical print, packaging and environmental artwork. A functioning prototype with meaningful decisions, alternate paths and two cross-channel additions.</p><p>The central tradeoff is intentional: add enough structure to protect understanding, while keeping the emotional value of a garment visible.</p></div><div><h3>The next validation is specific.</h3><p>Observe how people describe damage. Test expectations around “closest practical match.” Ask repairers which details they need. Print, fold and scan the physical pieces. Review the interface with keyboard and assistive technology.</p><p>No clients, interviews, repair outcomes, sales or environmental savings are claimed. The material and application images are labelled illustrations; flat artwork and product logic remain inspectable.</p></div></div>'''+links([('Read the full 15-phase refinement','afterform/refinement.html','Audit, deliverable matrix, tradeoffs and employer evidence'),('Explore the downloadable artwork','afterform/system.html#downloads','Identity, print, campaign and design tokens')]))
casehead='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AFTERFORM — Identity, graphic design & product / Jocelyn Martinez</title><meta name="description" content="A complete garment-repair identity, editorial, print and UX/UI ecosystem by Jocelyn Martinez."><link rel="icon" href="afterform/assets/system/micro-mark.svg"><link rel="stylesheet" href="afterform/afterform.css"><link rel="stylesheet" href="afterform/presentation.css"><link rel="stylesheet" href="afterform/refinement.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="portfolio-bridge wrap"><a href="index.html">Jocelyn Martinez<span>UX/UI + VISUAL DESIGN</span></a><nav aria-label="Portfolio"><a href="index.html#work">Work</a><a href="graphic-editions.html">Visual systems</a><a href="about.html">About</a></nav></header><main id="main">'''
(SITE.parent/'afterform.html').write_text(casehead+b+'''</main><footer class="presentation-footer wrap"><a href="index.html#work">← Back to selected work</a><p>Jocelyn Martinez / UX/UI + Visual Design<br>Self-directed, AI-assisted portfolio exploration.</p><a href="interval.html">Next: INTERVAL ↗</a></footer></body></html>''')
